package dustin.cex.domains.kyc;
import dustin.cex.domains.mail.*;
import java.sql.Timestamp;
import java.time.*;
import java.util.*;
import java.util.concurrent.*;
import org.junit.jupiter.api.Test;
import org.springframework.beans.factory.annotation.Autowired;
import org.springframework.http.MediaType;
import org.springframework.web.server.ResponseStatusException;
import static org.junit.jupiter.api.Assertions.*;
import static org.mockito.Mockito.*;
import static org.springframework.test.web.servlet.request.MockMvcRequestBuilders.*;
import static org.springframework.test.web.servlet.result.MockMvcResultMatchers.*;

/** 실제 세션·해시·로컬 SMTP·HTTP 경계로 이메일 소유만 검증하고 금융 권한은 변경하지 않는다. */
@org.junit.jupiter.api.extension.ExtendWith(org.springframework.boot.test.system.OutputCaptureExtension.class)
class CustomerEmailVerificationIntegrationTest extends CustomerMailTestSupport {
    @Autowired CustomerEmailVerification email;
    @Autowired CustomerMailRecipientPolicy recipients;
    @Autowired dustin.cex.domains.cdd.CddCrypto mailCrypto;
    CustomerEmailChallenges.Receipt request(){return email.request(customer.getId(),sid,UUID.randomUUID());}
    UUID job(UUID challenge){return jdbc.queryForObject("SELECT id FROM customer_mail_jobs WHERE reference_id=?",UUID.class,challenge);}
    String secret(CustomerEmailChallenges.Receipt r){return outbox.open(job(r.challengeId())).token();}
    @Test void onlyHashedTokenAndEncryptedMailAreStored(){var r=request();String token=secret(r);var row=jdbc.queryForMap("SELECT * FROM customer_email_challenges WHERE id=?",r.challengeId());assertFalse(row.toString().contains(token));assertFalse(row.toString().contains(customer.getEmail()));assertFalse(r.toString().contains(token));assertEquals(64,((String)row.get("token_hash")).length());assertFalse(email.status(customer.getId(),sid).verified());}
    @Test void sameKeyReturnsSameReceiptAndOneMail(){UUID key=UUID.randomUUID();var r=email.request(customer.getId(),sid,key);assertEquals(r,email.request(customer.getId(),sid,key));assertEquals(1,jdbc.queryForObject("SELECT count(*) FROM customer_mail_jobs WHERE reference_id=?",Long.class,r.challengeId()));}
    @Test void tokenReceivedByActualSmtpConfirmsOnceWithoutChangingUserVersion() throws Exception {long version=users.findById(customer.getId()).orElseThrow().getVersion();var r=request();dispatcher.dispatchOnce();assertTrue(server().waitForIncomingEmail(3000,1));String body=(String)server().getReceivedMessages()[0].getContent();String token=body.substring(body.indexOf("&token=")+7).strip();assertTrue(email.confirm(customer.getId(),sid,r.challengeId(),token).verified());assertTrue(email.confirm(customer.getId(),sid,r.challengeId(),token).verified());assertEquals(1,jdbc.queryForObject("SELECT count(*) FROM customer_email_confirmations WHERE challenge_id=?",Long.class,r.challengeId()));assertEquals(version,users.findById(customer.getId()).orElseThrow().getVersion());}
    @Test void wrongTokenAndForeignSessionDoNotVerify(){var r=request();assertThrows(ResponseStatusException.class,()->email.confirm(customer.getId(),sid,r.challengeId(),token()));assertThrows(ResponseStatusException.class,()->email.confirm(customer.getId(),maker.sid(),r.challengeId(),secret(r)));assertFalse(email.status(customer.getId(),sid).verified());}
    @Test void wrongTokenAfterConsumptionStillFails(){var r=request();email.confirm(customer.getId(),sid,r.challengeId(),secret(r));assertThrows(ResponseStatusException.class,()->email.confirm(customer.getId(),sid,r.challengeId(),token()));}
    @Test void changedAddressInvalidatesChallengeAndVerification(){var r=request();email.confirm(customer.getId(),sid,r.challengeId(),secret(r));var u=users.findById(customer.getId()).orElseThrow();u.setEmail(UUID.randomUUID()+"@other.invalid");users.saveAndFlush(u);assertFalse(email.status(customer.getId(),sid).verified());assertThrows(ResponseStatusException.class,()->email.confirm(customer.getId(),sid,r.challengeId(),secret(r)));}
    @Test void disabledAccountCannotConfirm(){var r=request();var u=users.findById(customer.getId()).orElseThrow();u.setEnabled(false);users.saveAndFlush(u);assertThrows(ResponseStatusException.class,()->email.confirm(customer.getId(),sid,r.challengeId(),secret(r)));}
    @Test void expiredChallengeCannotConfirm(){UUID id=UUID.randomUUID();String token=token();jdbc.update("INSERT INTO customer_email_challenges(id,user_id,request_key,email_mac,rate_mac,key_id,token_hash,expires_at) VALUES(?,?,?,?,?,?,?,?)",id,customer.getId(),UUID.randomUUID(),recipients.addressMac(customer.getEmail()),mailCrypto.fingerprint("customer-email-rate-v1",customer.getEmail()),mailCrypto.keyId(),sha(id+":"+token),Timestamp.from(Instant.now().minusSeconds(1)));var e=assertThrows(ResponseStatusException.class,()->email.confirm(customer.getId(),sid,id,token));assertEquals(410,e.getStatusCode().value());}
    @Test void verificationAuditFailureRollsBackTokenConsumption(){var r=request();doThrow(new IllegalStateException("격리 감사 실패")).when(audit).record(eq(customer.getId()),eq("CUSTOMER_EMAIL_VERIFIED"),anyString(),anyString(),anyString());assertThrows(IllegalStateException.class,()->email.confirm(customer.getId(),sid,r.challengeId(),secret(r)));reset(audit);assertFalse(email.status(customer.getId(),sid).verified());assertTrue(email.confirm(customer.getId(),sid,r.challengeId(),secret(r)).verified());}
    @Test void requestAuditFailureRollsBackChallengeAndMail(){UUID key=UUID.randomUUID();doThrow(new IllegalStateException("격리 감사 실패")).when(audit).record(eq(customer.getId()),eq("CUSTOMER_EMAIL_REQUESTED"),anyString(),anyString(),anyString());assertThrows(IllegalStateException.class,()->email.request(customer.getId(),sid,key));reset(audit);assertEquals(0,jdbc.queryForObject("SELECT count(*) FROM customer_email_challenges WHERE user_id=?",Long.class,customer.getId()));assertEquals(0,jdbc.queryForObject("SELECT count(*) FROM customer_mail_jobs WHERE user_id=?",Long.class,customer.getId()));}
    @Test void newRequestWithinCooldownIsRejectedButReplayWorks(){UUID key=UUID.randomUUID();var r=email.request(customer.getId(),sid,key);assertEquals(429,assertThrows(ResponseStatusException.class,this::request).getStatusCode().value());assertEquals(r,email.request(customer.getId(),sid,key));}
    @Test void fifthWrongTokenLimitsFurtherAttempts(){var r=request();for(int i=0;i<5;i++)assertEquals(403,assertThrows(ResponseStatusException.class,()->email.confirm(customer.getId(),sid,r.challengeId(),token())).getStatusCode().value());assertEquals(429,assertThrows(ResponseStatusException.class,()->email.confirm(customer.getId(),sid,r.challengeId(),secret(r))).getStatusCode().value());}
    @Test void concurrentConfirmationHasOneEffect() throws Exception {var r=request();String token=secret(r);var pool=Executors.newFixedThreadPool(2);try{var a=pool.submit(()->email.confirm(customer.getId(),sid,r.challengeId(),token));var b=pool.submit(()->email.confirm(customer.getId(),sid,r.challengeId(),token));assertTrue(a.get(10,TimeUnit.SECONDS).verified());assertTrue(b.get(10,TimeUnit.SECONDS).verified());assertEquals(1,jdbc.queryForObject("SELECT count(*) FROM customer_email_confirmations WHERE challenge_id=?",Long.class,r.challengeId()));}finally{pool.shutdownNow();}}
    @Test void httpNeverReturnsTokenAndGetDoesNotConsume() throws Exception {var result=mvc.perform(post("/api/customer/email/challenges").header("Authorization","Bearer "+customerAccess).header("Idempotency-Key",UUID.randomUUID())).andExpect(status().isOk()).andReturn();var r=json.readValue(result.getResponse().getContentAsString(),CustomerEmailChallenges.Receipt.class);assertFalse(result.getResponse().getContentAsString().contains(secret(r)));mvc.perform(get("/api/customer/email/confirmations").header("Authorization","Bearer "+customerAccess).param("challengeId",r.challengeId().toString()).param("token",secret(r))).andExpect(status().isForbidden());assertFalse(email.status(customer.getId(),sid).verified());mvc.perform(post("/api/customer/email/confirmations").header("Authorization","Bearer "+customerAccess).contentType(MediaType.APPLICATION_JSON).content(json.writeValueAsString(Map.of("challengeId",r.challengeId(),"token",secret(r))))).andExpect(status().isOk()).andExpect(jsonPath("$.verified").value(true));}
    @Test void anonymousAndOperatorCannotRequestVerification() throws Exception {mvc.perform(post("/api/customer/email/challenges").header("Idempotency-Key",UUID.randomUUID())).andExpect(status().isUnauthorized());mvc.perform(post("/api/customer/email/challenges").header("Authorization","Bearer "+maker.access()).header("Idempotency-Key",UUID.randomUUID())).andExpect(status().isForbidden());}
    @Test void ownershipRecordsAreImmutable(){var r=request();email.confirm(customer.getId(),sid,r.challengeId(),secret(r));for(String table:List.of("customer_email_challenges","customer_email_confirmations"))for(String sql:List.of("UPDATE "+table+" SET user_id=user_id","DELETE FROM "+table,"TRUNCATE "+table+" CASCADE"))assertThrows(org.springframework.dao.DataAccessException.class,()->jdbc.execute(sql));}
    @Test void hourlyLimitUsesHistoricalRequestsWithoutRewritingThem(){
        // 과거 접수 표본을 추가한다. 이미 존재하는 불변 기록이나 현재 시각을 수정하지 않는다.
        for(int i=0;i<3;i++){UUID id=UUID.randomUUID();jdbc.update("INSERT INTO customer_email_challenges(id,user_id,request_key,email_mac,rate_mac,key_id,token_hash,expires_at,created_at) VALUES(?,?,?,?,?,?,?,?,?)",id,customer.getId(),UUID.randomUUID(),recipients.addressMac(customer.getEmail()),mailCrypto.fingerprint("customer-email-rate-v1",customer.getEmail().toLowerCase(Locale.ROOT)),mailCrypto.keyId(),sha(id+":"+token()),Timestamp.from(Instant.now().minusSeconds(100)),Timestamp.from(Instant.now().minusSeconds(120+i)));}
        assertEquals(429,assertThrows(ResponseStatusException.class,this::request).getStatusCode().value());
    }
    @Test void concurrentNewRequestsReserveOnlyOneMail() throws Exception {var pool=Executors.newFixedThreadPool(2);try{java.util.concurrent.Callable<Boolean> send=()->{try{request();return true;}catch(ResponseStatusException e){assertEquals(429,e.getStatusCode().value());return false;}};var a=pool.submit(send);var b=pool.submit(send);assertNotEquals(a.get(10,TimeUnit.SECONDS),b.get(10,TimeUnit.SECONDS));assertEquals(1,jdbc.queryForObject("SELECT count(*) FROM customer_mail_jobs WHERE user_id=?",Long.class,customer.getId()));}finally{pool.shutdownNow();}}

    @Test void malformedTokenIsRejectedWithoutAppearingInLogs(org.springframework.boot.test.system.CapturedOutput output) throws Exception {
        var r=request();String malformed=secret(r)+"!";
        // 유효 토큰을 일부 포함한 잘못된 입력도 비밀이다. 기본 바인딩 오류의 rejected value에 남기지 않는다.
        mvc.perform(post("/api/customer/email/confirmations").header("Authorization","Bearer "+customerAccess).contentType(MediaType.APPLICATION_JSON).content(json.writeValueAsString(Map.of("challengeId",r.challengeId(),"token",malformed)))).andExpect(status().isBadRequest());
        mvc.perform(post("/api/customer/email/confirmations").header("Authorization","Bearer "+customerAccess).contentType(MediaType.APPLICATION_JSON).content(json.writeValueAsString(Map.of("challengeId",r.challengeId(),"token",List.of(secret(r)))))).andExpect(status().isBadRequest());
        mvc.perform(post("/api/customer/email/confirmations").header("Authorization","Bearer "+customerAccess).contentType(MediaType.APPLICATION_JSON).content(json.writeValueAsString(Map.of("token",secret(r))))).andExpect(status().isBadRequest());
        assertFalse(email.status(customer.getId(),sid).verified());assertFalse(output.getAll().contains(secret(r)),"입력 토큰은 검증 오류 로그에 남으면 안 됩니다");
    }

}
